// src/App.js — map ra danh sách, key = id ổn định
const MENU = [
  { id: 'e1', name: 'Espresso', price: 35000 },
  { id: 'c2', name: 'Cappuccino', price: 45000 },
  { id: 't3', name: 'Peach Tea', price: 40000 },
];

export default function App() {
  return (
    <section>
      <h2>Menu</h2>
      <ul id="menu">
        {MENU.map((item) => (
          <li key={item.id} className="menu-item">
